import math
from itertools import combinations, permutations

def get_divisors(m):
    divs = []
    for i in range(1, int(math.sqrt(m)) + 1):
        if m % i == 0:
            divs.append(i)
            if i * i != m:
                divs.append(m // i)
    return sorted(divs)

def sigma(m, divisors):
    return sum(divisors)

def is_perfect_square(n):
    if n < 0:
        return False
    sqrt_n = int(math.sqrt(n))
    return sqrt_n * sqrt_n == n

def solve_m(m):
    divisors = get_divisors(m)
    n = len(divisors)
    sigma_m = sigma(m, divisors)

    if not is_perfect_square(sigma_m):
        return "No"

    target_sum_sq = int(math.sqrt(sigma_m))

    # We are looking for a sequence of perfect squares 0=k_0^2 < k_1^2 < ... < k_n^2 = sigma(m)
    # such that the differences a_i = k_i^2 - k_{i-1}^2 are exactly the divisors of m.

    # Since n is small (at most 6 for m <= 20), we can iterate over all ways to partition the steps.

    # Find all possible sequences of square roots k_1, ..., k_{n-1}
    # such that 0 < k_1 < ... < k_{n-1} < target_sum_sq.

    # The possible integer values for k are from 1 up to target_sum_sq - 1.
    possible_k = list(range(1, target_sum_sq))

    # We need to choose n-1 intermediate values from possible_k.
    # This is a combination search.

    for k_sequence_tuple in combinations(possible_k, n - 1):
        K = [0] + list(k_sequence_tuple) + [target_sum_sq]

        # Check if this sequence of K generates the required divisors
        generated_divisors = []
        for i in range(1, n + 1):
            a_i = K[i]**2 - K[i-1]**2
            generated_divisors.append(a_i)

        # Check if the generated set of divisors matches the original set of divisors
        # Since both lists are sorted for comparison, we check if they are equal.
        if sorted(generated_divisors) == divisors:
            return "Yes"

    return "No"

